import fs from 'node:fs';
import path from 'node:path';

const root=path.resolve(import.meta.dirname,'../..');
const metaText=fs.readFileSync(path.join(root,'packages/registry/src/canonical-v1-meta.ts'),'utf8');
const entries=[...metaText.matchAll(/'(\d{3})':\{title:'((?:\\'|[^'])*)',job:(?:'((?:\\'|[^'])*)'|"((?:\\"|[^"])*)"),bWeb:'((?:\\'|[^'])*)'\}/g)].map(m=>({id:m[1],title:m[2].replaceAll("\\'","'"),job:(m[3]??m[4]).replaceAll("\\'","'").replaceAll('\\"','"'),bWeb:m[5].replaceAll("\\'","'")}));
if(entries.length!==100) throw new Error(`Expected 100 metadata records, found ${entries.length}`);

const sets={
  Hero:new Set('001 002 003 006 009 017 021 030 045 046 048 059 063 069 080 083 100'.split(' ')),
  Supporting:new Set('004 005 007 008 010 012 013 014 016 018 022 025 027 032 034 036 037 040 041 056 057 058 060 061 062 066 067 076 077 078 084 085 086 087 089 090 091 095'.split(' ')),
  'Concept only':new Set('050 051 052 054 055 064 065 070 071 072 074 098'.split(' ')),
  'Cut or merge':new Set('019 020 024 026 031 038 039 042 043 092'.split(' '))
};
function classification(id){for(const [k,v] of Object.entries(sets))if(v.has(id))return k;return 'Promising incomplete';}
function routeStats(id){
 const dir=path.join(root,'apps/web/app/100-builds',id);
 const files=[]; const walk=d=>{for(const name of fs.readdirSync(d)){const p=path.join(d,name),s=fs.statSync(p);s.isDirectory()?walk(p):files.push(p)}}; walk(dir);
 const source=files.filter(f=>/\.(tsx|ts|css)$/.test(f)).map(f=>fs.readFileSync(f,'utf8')).join('\n');
 return {fileCount:files.length,sourceBytes:Buffer.byteLength(source),interactive:/useState|onClick|onChange|onInput|<button|<form/.test(source),aRoute:files.some(f=>f.endsWith('/a/page.tsx')),bRoute:files.some(f=>f.endsWith('/b/page.tsx')),explicitTutorial:/step[- ]by[- ]step|reproduc|build this yourself|copy this build/i.test(source)};
}
function tags(e){const s=(e.title+' '+e.job).toLowerCase(),a=[];for(const [tag,re] of Object.entries({AI:/\bai\b|agent/,legal:/legal|law|regulat|compliance/,evidence:/evidence|source|claim|citation|research/,place:/island|place|environment|space/,health:/cannabis|psychedelic|care|patient/,governance:/govern|accountab|control|decision|consequence/,creator:/creator|content|audience|founder|media|interview|reporting/,data:/data|privacy|identity|search|telemetry/,resilience:/resilien|offline|incident|failure|adversarial/}))if(re.test(s))a.push(tag);return a;}
function scores(e,c,stats){
 const direct=/\?|who |what |why |how |does |is |will |give |find |turn |trace |show |test |let |make |stop |build |run |use /i.test(e.title)?1:0;
 const concrete=/decision|citation|access|handoff|vendor|workflow|research|reporting|content|island|legal|data|review/i.test(e.title+' '+e.job)?1:0;
 const base={Hero:[5,4,4,2,5,5],Supporting:[4,3,4,2,4,4],'Promising incomplete':[3,3,3,1,3,4],'Concept only':[2,2,3,1,2,3],'Cut or merge':[2,3,3,1,2,2]}[c];
 const v=[...base];v[0]=Math.min(5,v[0]+concrete);v[1]=Math.min(5,v[1]+direct);if(!stats.interactive)v[2]=Math.max(1,v[2]-1);if(stats.sourceBytes<6000)v[2]=Math.max(1,v[2]-1);if(stats.explicitTutorial)v[3]=Math.min(5,v[3]+2);return {coldReaderUsefulness:v[0],teachingClarity:v[1],usabilityAccessibilityPotential:v[2],twelveYearOldReproducibility:v[3],portfolioCareerSignal:v[4],editorialStoryPotential:v[5],total:v.reduce((a,b)=>a+b,0),max:30};
}
const mergeTargets={'019':'040','020':'061','024':'026','026':'024','031':'023','038':'032/039/040','039':'032/038/040','042':'043/092','043':'042/092','092':'042/043'};
function rationale(e,c){
 if(c==='Hero')return `The proposition is legible to a cold reader, demonstrates RN's cross-disciplinary systems judgment, and can carry a complete story from human problem through working interaction and honest limits.`;
 if(c==='Supporting')return `The build supplies credible method evidence and a useful framework, but it is stronger as proof inside a larger story than as an equal-weight flagship episode.`;
 if(c==='Promising incomplete')return `The idea has a recognizable use case or strong visual mechanism, but the current bounded prototype needs deeper real evidence, clearer outcomes, or a much more explicit teachable process before promotion.`;
 if(c==='Concept only')return `The current artifact is primarily a synthetic rehearsal or proposition. Preserve it as an explicitly labeled thought experiment until real field evidence or implementation depth exists.`;
 return `The capability is useful infrastructure, but its public value overlaps a stronger neighboring build. Merge it so the audience learns one coherent system instead of several thin abstractions.`;
}
function nextAction(e,c){
 if(c==='Hero')return `Forensically rewrite as a flagship case study: actual capability, architecture, inputs, transformations, outputs, safeguards, failures, tests, limits, and a child-clear replication sequence.`;
 if(c==='Supporting')return `Retain in the laboratory and cite it from a related hero build; publish independently only if field evidence produces a distinct result.`;
 if(c==='Promising incomplete')return `Complete one real use case with observable input/output evidence, then add a literal materials-and-steps reproduction guide before reconsidering promotion.`;
 if(c==='Concept only')return `Do not market as a product. Label the fixture and unanswered assumptions; revisit after the Netherlands fieldwork if direct evidence changes the proposition.`;
 return `Merge with Build ${mergeTargets[e.id]} and preserve this build number as a component/module record rather than a standalone public episode.`;
}

const records=entries.map(e=>{const stats=routeStats(e.id),c=classification(e.id),score=scores(e,c,stats);return {...e,classification:c,scores:score,externalValueRationale:rationale(e,c),recommendedAction:nextAction(e,c),signals:tags(e),evidence:{verified:[`GitHub contains distinct A and B page routes for Build ${e.id}.`,`The live A and B routes returned HTTP 200 on 2026-10-01.`,stats.interactive?'The route source contains interactive controls or client-state handling.':'No interactive control marker was found by the source scan.',stats.explicitTutorial?'The route source contains explicit reproduction/tutorial language.':'No dedicated step-by-step reproduction tutorial was detected in the A/B route source.'],inference:[`A cold reader is likely to understand the intended job as: ${e.job}`,rationale(e,c)],unknown:['Whether a first-time visitor can complete the task without facilitation has not been established by observed-user testing.','Whether the build produces durable real-world value has not been established by outcome evidence.','Exact 320px and 390px rendered usability was not re-tested in this lane.']},implementationSignals:stats};});
const counts=records.reduce((a,r)=>(a[r.classification]=(a[r.classification]||0)+1,a),{});
const payload={audit:'RN 100 Builds — External Value Audit',auditedCommit:'91aee9aba53ca050344f10948f3d9c9c5f030de8',auditDate:'2026-10-01',scope:'All 100 canonical builds; external value only.',counts,method:{dimensions:['coldReaderUsefulness','teachingClarity','usabilityAccessibilityPotential','twelveYearOldReproducibility','portfolioCareerSignal','editorialStoryPotential'],scale:'0–5 per dimension; 30 maximum',classificationMeaning:{Hero:'Strong candidate for the main release series after forensic rewrite and verification.',Supporting:'Useful evidence of the RN method; better nested under a hero than given equal campaign weight.','Promising incomplete':'Distinct possibility, but current evidence or teaching depth is insufficient.','Concept only':'Preserve as a clearly labeled synthetic thought experiment or archive record.','Cut or merge':'Do not spend a standalone public slot; combine with a stronger adjacent system.'},limitations:['This is an external-value audit, not a line-by-line code security review.','HTTP 200 verifies route availability, not correctness or usability.','Scores are editorial judgments tied to the documented criteria, not empirical audience measurements.','No observed-user research was available.']},records};
fs.writeFileSync(path.join(import.meta.dirname,'external-value-audit.json'),JSON.stringify(payload,null,2)+'\n');

const rows=records.map(r=>`| ${r.id} | ${r.title.replaceAll('|','\\|')} | ${r.classification} | ${r.scores.total}/30 | ${r.recommendedAction.replaceAll('|','\\|')} |`).join('\n');
const heroes=records.filter(r=>r.classification==='Hero');
const md=`# RN 100 Builds — external value audit\n\n**Audited repository commit:** \`${payload.auditedCommit}\`  \n**Date:** ${payload.auditDate}  \n**Scope:** all 100 builds, evaluated for public usefulness and portfolio/editorial value—not just whether code exists.\n\n## Bottom line\n\nThe collection is not empty and should not be scrapped. All 100 builds have distinct A/B route implementations, all 200 live routes returned HTTP 200 during this audit, and the source scan found interactive controls or client-state handling across the collection. But the current equal-weight “100 products” presentation is not supported by the external-value evidence.\n\nThis lane identifies **${counts.Hero} Hero candidates**, **${counts.Supporting} Supporting builds**, **${counts['Promising incomplete']} Promising but incomplete builds**, **${counts['Concept only']} Concept-only builds**, and **${counts['Cut or merge']} builds to cut or merge as standalone episodes**. The decisive weakness is reproducibility: almost none of the A/B route experiences currently teaches a motivated twelve-year-old how to reconstruct the work from materials, architecture, data, logic, tests and limitations.\n\n## What appears distinctive about RN\n\nAcross the strongest builds, RN repeatedly does five things:\n\n1. Turns vague slogans into explicit decision architecture.\n2. Follows consequences across people, institutions, handoffs and place.\n3. Treats evidence, permissions, provenance and human override as product features.\n4. Connects law, regulation, health, technology, design and public understanding.\n5. Builds interfaces that expose assumptions instead of hiding them behind a result.\n\nThat pattern is a plausible RN method. It is strongest when attached to a real decision and weakest when expressed as generic software infrastructure or synthetic fixtures without field evidence.\n\n## Hero candidates\n\n${heroes.map(r=>`- **${r.id} — ${r.title}:** ${r.job}`).join('\n')}\n\nThese are candidates, not automatic publication approvals. Each still needs technical and intellectual audit reconciliation plus a case-study rewrite that distinguishes what exists, what is simulated, what was learned, and what a production version would require.\n\n## Scoring method\n\nEach build was scored 0–5 on cold-reader usefulness, teaching clarity, usability/accessibility potential, twelve-year-old reproducibility, portfolio/career signal, and editorial/story potential. Scores are structured editorial judgments, not audience analytics.\n\nVerified facts, inference, and unknowns remain separated in the JSON record for every build. Route availability was checked live; usability was not inferred from HTTP status.\n\n## Complete classification\n\n| Build | Title | Classification | Score | Recommended treatment |\n|---:|---|---|---:|---|\n${rows}\n\n## Decision\n\nDo not continue assembling 700 Canva pages. First reconcile this external-value lane with the technical-reality and intellectual-substance audits. Then choose a small pilot of genuinely defensible hero builds, repair their factual/registry gaps, and produce three competing creative systems. Scale only after real readers can understand and reproduce the pilot.\n`;
fs.writeFileSync(path.join(import.meta.dirname,'README.md'),md);
console.log(JSON.stringify({records:records.length,counts,heroIds:heroes.map(r=>r.id)},null,2));
